import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.util.logging.*;

@WebServlet("/api/users")
public class UserSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(UserSearchServlet.class.getName());

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String department = req.getParameter("dept");
        String role = req.getParameter("role");
        String sortBy = req.getParameter("sort");

        // Input length validation
        if (department != null && department.length() > 64) {
            resp.sendError(400, "Invalid department parameter");
            return;
        }
        if (role != null && role.length() > 32) {
            resp.sendError(400, "Invalid role parameter");
            return;
        }

        // Whitelist sort columns
        String safeSort = "last_name";
        if ("email".equals(sortBy) || "hire_date".equals(sortBy) || "last_name".equals(sortBy)) {
            safeSort = sortBy;
        }

        StringBuilder query = new StringBuilder(
            "SELECT employee_id, first_name, last_name, email, department, role "
            + "FROM employees WHERE active = true"
        );

        if (department != null && !department.isEmpty()) {
            // Filter by department - using string concatenation for LIKE clause
            query.append(" AND department LIKE '%" + department + "%'");
        }

        if (role != null && !role.isEmpty()) {
            query.append(" AND role = '" + role + "'");
        }

        query.append(" ORDER BY " + safeSort + " ASC LIMIT 100");

        log.info("Executing user search: dept=" + department + " role=" + role);

        resp.setContentType("application/json");
        resp.setCharacterEncoding("UTF-8");

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query.toString())) {

            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                first = false;
                json.append("  {")
                    .append("\"id\":").append(rs.getInt("employee_id")).append(",")
                    .append("\"firstName\":\"").append(escapeJson(rs.getString("first_name"))).append("\",")
                    .append("\"lastName\":\"").append(escapeJson(rs.getString("last_name"))).append("\",")
                    .append("\"email\":\"").append(escapeJson(rs.getString("email"))).append("\",")
                    .append("\"department\":\"").append(escapeJson(rs.getString("department"))).append("\",")
                    .append("\"role\":\"").append(escapeJson(rs.getString("role"))).append("\"")
                    .append("}");
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
